from time import sleep
from typing import List, Tuple, Type

from .message_handling import Query, BasicQueryManager
from .msg_cell_list import CellListInterface
from .msg_user_list import UserListInterface
from .msg_service import ServiceInterface
from .msg_general_report import (
    BrowserStartGeneralReportReq, BrowserStartGeneralReportResp, BrowserGeneralReportInd,
    BrowserStopGeneralReportReq, BrowserStopGeneralReportResp, BrowserGeneralReportIndSink,
)
from ..commons import LOGGER, TRACE_STORE
from ..collectors import BaseTraceCollector
from ..utils import get_context_id, get_procedure_id
from .sack_reflection_interface import EBrowserObjectName, VALUE_NOT_SET


class StartThroughputQuery(Query):
    def __init__(self, req, resp):
        super(StartThroughputQuery, self).__init__(req, resp)

    def fill_req_msg(self, report_name, meas_period, cell_id=VALUE_NOT_SET, user_id=VALUE_NOT_SET):
        # type: (int, int, int, int) -> None
        self.req_msg.contextId = (get_context_id() << 16) | (report_name & 0xffff)
        self.req_msg.procedureId = get_procedure_id()

        self.req_msg.reportName = report_name
        self.req_msg.reportPeriod = meas_period
        self.req_msg.startSfn = 0xffffffff
        self.req_msg.reportingDuration = 0
        self.req_msg.reportGranularityScale = 1
        self.req_msg.numberOfAssociatedObjects = 1

        if cell_id == VALUE_NOT_SET and user_id == VALUE_NOT_SET:
            self.req_msg.dynamicData[0] = EBrowserObjectName.EBrowserObjectName_LocalCellGroup
            self.req_msg.dynamicData[1] = 0

        if cell_id == VALUE_NOT_SET and user_id != VALUE_NOT_SET:
            self.req_msg.dynamicData[0] = EBrowserObjectName.EBrowserObjectName_User
            self.req_msg.dynamicData[1] = user_id

        if cell_id != VALUE_NOT_SET and user_id == VALUE_NOT_SET:
            self.req_msg.dynamicData[0] = EBrowserObjectName.EBrowserObjectName_Cell
            self.req_msg.dynamicData[1] = cell_id

    def _handle_response(self):
        status = self.resp_msg.status
        if status != 0:
            LOGGER.warning('Throughput start error (BrowserStartGeneralReportResp with status {}) '.format(status))


class StopThroughputQuery(Query):
    def __init__(self, req, resp):
        super(StopThroughputQuery, self).__init__(req, resp)

    def fill_req_msg(self, report_name, context_id, procedure_id):
        # type: (int, int, int) -> None
        self.req_msg.contextId = context_id
        self.req_msg.procedureId = procedure_id
        self.req_msg.reportName = report_name

    def _handle_response(self):
        status = self.resp_msg.status
        if status != 0:
            LOGGER.warning('Throughput stop error (BrowserStopGeneralReportResp with status {}) '.format(status))


class ThroughputCollector(BaseTraceCollector):
    def __init__(self, connection):
        super(ThroughputCollector, self).__init__(connection)
        self.cell_id = None  # type: int
        self.user_id = None  # type: int
        self.meas_name = self.trace_name = None  # type: str

    def set_parameters(self, **kwargs):
        self.report_name = EBrowserObjectName.EBrowserObjectName_EDpdchThroughput

        super(ThroughputCollector, self).set_parameters(**kwargs)

    def prepare_query_managers(self):
        if not self:
            return

        board, cpu = self.board, self.cpu

        start_query = StartThroughputQuery(BrowserStartGeneralReportReq(board, cpu), BrowserStartGeneralReportResp())
        start_query.fill_req_msg(self.report_name, self.meas_period, self.cell_id, self.user_id)

        context_id, procedure_id = start_query.req_msg.contextId, start_query.req_msg.procedureId
        stop_query = StopThroughputQuery(BrowserStopGeneralReportReq(board, cpu), BrowserStopGeneralReportResp())
        stop_query.fill_req_msg(self.report_name, context_id, procedure_id)

        self.start_qm = BasicQueryManager(start_query, self.connection)
        self.stop_qm = BasicQueryManager(stop_query, self.connection)
        self.ind_m = BrowserGeneralReportIndSink(cookie=(BrowserGeneralReportInd.id, context_id, procedure_id))

    def find_target_board_cpu(self, cell_id):
        candidate_board_and_cpu_ids = self._find_candidate_board_cpu()
        target_board, target_cpu = self._find_target_board_cpu(cell_id, candidate_board_and_cpu_ids)

        if not target_cpu:
            LOGGER.warning(
                'Could not determine board and CPU for getting {} for cell {}'.format(self.meas_name, cell_id)
            )
            return

        self.board, self.cpu = target_board, target_cpu

    def _find_candidate_board_cpu(self):
        services = ServiceInterface(self.connection)
        candidate_board_and_cpu_ids = services.get_board_cpu_pairs_with_given_service_or_message(self.report_name)
        return candidate_board_and_cpu_ids

    def _find_target_board_cpu(self, cell_id, candidate_board_and_cpu_ids):
        raise NotImplementedError


class CellThroughputCollector(ThroughputCollector):
    def __init__(self, connection):
        super(CellThroughputCollector, self).__init__(connection)
        self.meas_name = self.trace_name = 'Cell_throughput'
        self.user_id = VALUE_NOT_SET

    def _find_target_board_cpu(self, cell_id, candidate_board_and_cpu_ids):
        # type: (int, List[int]) -> Tuple[int, int]

        self.cell_id = cell_id  # !

        target_board, target_cpu = None, None
        for board, cpu in candidate_board_and_cpu_ids:
            trial_cell_ids = CellListInterface(self.connection).get_cell_ids(board, cpu)
            hsupa_user_ids = UserListInterface(self.connection).get_hsupa_user_ids(board, cpu)
            if hsupa_user_ids and cell_id in trial_cell_ids:
                target_board, target_cpu = board, cpu
                break
        return target_board, target_cpu


class CpuThroughputCollector(ThroughputCollector):
    def __init__(self, connection):
        super(CpuThroughputCollector, self).__init__(connection)
        self.meas_name = self.trace_name = 'CPU_throughput'
        self.user_id = VALUE_NOT_SET
        self.cell_id = VALUE_NOT_SET

    def _find_target_board_cpu(self, cell_id, candidate_board_and_cpu_ids):
        # type: (int, List[int]) -> Tuple[int, int]
        target_board, target_cpu = None, None
        for board, cpu in candidate_board_and_cpu_ids:
            trial_cell_ids = CellListInterface(self.connection).get_cell_ids(board, cpu)
            if cell_id in trial_cell_ids:
                target_board, target_cpu = board, cpu
                break

        return target_board, target_cpu


class UserThroughputCollector(ThroughputCollector):
    def __init__(self, connection):
        super(UserThroughputCollector, self).__init__(connection)
        self.meas_name = self.trace_name = 'User_throughput'
        self.cell_id = VALUE_NOT_SET

    def _find_target_board_cpu(self, cell_id, candidate_board_and_cpu_ids):
        # type: (int, List[int]) -> Tuple[int, int]
        target_board, target_cpu = None, None
        user_id = None
        for board, cpu in candidate_board_and_cpu_ids:
            trial_cell_ids = CellListInterface(self.connection).get_cell_ids(board, cpu)
            hsupa_user_ids = UserListInterface(self.connection).get_hsupa_user_ids(board, cpu)
            if hsupa_user_ids and cell_id in trial_cell_ids:
                self.user_id = hsupa_user_ids[0]
                target_board, target_cpu = board, cpu
                break

        if not user_id:
            LOGGER.warning('Could not find user for getting {} for cell {}'.format(self.meas_name, cell_id))

        return target_board, target_cpu


class ThroughputInterface(object):
    def __init__(self, connection):
        self.connection = connection

    def _prepare_throughput_collector(self, cell_id, throughput_collector_cls):
        # type: (int, Type[ThroughputCollector]) -> ThroughputCollector
        meas_period = 100  # ms

        collector = throughput_collector_cls(self.connection)
        collector.set_parameters(
            meas_period=meas_period
        )
        collector.find_target_board_cpu(cell_id)
        collector.prepare_query_managers()

        cell_ = collector.cell_id if collector.cell_id != VALUE_NOT_SET else -1
        user_ = collector.user_id if collector.user_id != VALUE_NOT_SET else -1
        LOGGER.info('{} will be collected from 0x{:x}{:x}, cell {}, user {}'.format(
            collector.meas_name, collector.board, collector.cpu, cell_, user_)
        )

        return collector

    def prepare_cell_throughput_collector(self, cell_id):
        return self._prepare_throughput_collector(cell_id, CellThroughputCollector)

    def _collect_throughput(self, cell_id, meas_time, output_path, trace_alias, throughput_collector_cls):
        # type: (int, int, str, str, Type[ThroughputCollector]) -> None
        collector = self._prepare_throughput_collector(cell_id, throughput_collector_cls)

        if not collector:
            return

        TRACE_STORE.add(collector, trace_alias)

        collector.start()
        sleep(meas_time)
        collector.stop()
        collector.save_traces(output_path)

    def collect_cell_throughput(self, cell_id, meas_time, output_path, trace_alias):
        self._collect_throughput(cell_id, meas_time, output_path, trace_alias, CellThroughputCollector)

    def collect_cpu_throughput(self, cell_id, meas_time, output_path, trace_alias):
        self._collect_throughput(cell_id, meas_time, output_path, trace_alias, CpuThroughputCollector)

    def collect_user_throughput(self, cell_id, meas_time, output_path, trace_alias):
        self._collect_throughput(cell_id, meas_time, output_path, trace_alias, UserThroughputCollector)
